import{_ as a,o,c as r,a0 as t}from"./chunks/framework.BFLrGO6w.js";const h=JSON.parse('{"title":"FFLogs 對帳建議與待驗證項目","description":"","frontmatter":{},"headers":[],"relativePath":"recommends/genimi/recommendations.md","filePath":"recommends/genimi/recommendations.md"}'),s={name:"recommends/genimi/recommendations.md"};function i(n,e,d,c,l,p){return o(),r("div",null,[...e[0]||(e[0]=[t(`<h1 id="fflogs-對帳建議與待驗證項目" tabindex="-1">FFLogs 對帳建議與待驗證項目 <a class="header-anchor" href="#fflogs-對帳建議與待驗證項目" aria-label="Permalink to &quot;FFLogs 對帳建議與待驗證項目&quot;">​</a></h1><p>2026-09-10 文件 review：實作進度以 <code>doc/project-progress.md</code> 為唯一入口，現行公式以 <a href="./../../formulas-qa.html">公式與限制</a> 為準。建議不代表已實作，也不以尚未核實的公式宣稱 FFLogs 官方規則。</p><h2 id="已修正的舊建議" tabindex="-1">已修正的舊建議 <a class="header-anchor" href="#已修正的舊建議" aria-label="Permalink to &quot;已修正的舊建議&quot;">​</a></h2><ul><li><strong>撤回全面移除 <code>addConsumedKnownCapacityRemainder</code> 的要求。</strong> v54 已將中間學派 barrier 辨識為 <code>781</code>，容量為同 frame <code>90A6</code> 回復量的 125%；提前移除可作為逐目標耗盡證據，<code>F36</code> 則是 HoT。自然到期不計未耗餘額，覆蓋與多盾情境仍須個別驗證，不能把所有狀態移除概括為破盾或全部排除。</li><li><strong>撤回統一改寫所有 overheal 分母的要求。</strong> 戰鬥摘要使用 <code>overheal / raw healing</code>；治療表與 FFLogs 未含 mitigation 子口徑使用 <code>overheal / (raw healing + consumed absorbs)</code>。兩個欄位用途不同，不能全域取代。</li><li><strong>CPM 純 buff／utility 施放已納入。</strong> parserVersion 25 已移除必須有傷害或治療效果的條件，仍排除自動攻擊並去重 AoE；後續只追查具體漏記事件。</li><li><strong>戰鬥邊界差異須逐事件對齊。</strong> 不以本案例約 0.67 秒差距作通用修正量，也不把開怪倒數直接當成戰鬥開始。</li></ul><h2 id="治療對帳的有效工作" tabindex="-1">治療對帳的有效工作 <a class="header-anchor" href="#治療對帳的有效工作" aria-label="Permalink to &quot;治療對帳的有效工作&quot;">​</a></h2><ul><li>保留 v54 中間學派 <code>784,100</code>、AST absorbs <code>921,814</code> 的校準紀錄；AST 與本案例 FFLogs 的剩餘盾差為 F34 <code>15,036</code>，仍需完整容量與狀態證據。</li><li>SCH 三筆完全吸收事件缺口合計 <code>82,390</code>，本地 type 22 damage amount 與 HP 變化均為 0；維持已知限制。不得以報告差額或固定倍率回填。</li><li>繼續核對 effective healing、同 server frame HP snapshot 與 action sync 配對。以逐事件證據判定差異，不把 comparator 差異總數當成根因分類。</li><li>Comparator 缺失／非有限數值檢查及六種分類已由工作包 A 完成並整合；未提供的 baseline 欄位顯示未比較。下一步選定 CI 採用欄位及 coverage 政策。</li></ul><h2 id="減傷-保留總量公式-撤回不守恆的分配公式" tabindex="-1">減傷：保留總量公式，撤回不守恆的分配公式 <a class="header-anchor" href="#減傷-保留總量公式-撤回不守恆的分配公式" aria-label="Permalink to &quot;減傷：保留總量公式，撤回不守恆的分配公式&quot;">​</a></h2><p>以下僅為已知乘法減傷且資料完整時的數學模型，尚非本專案已實作或已驗證的 FFLogs 歸因規格。令 <code>D0</code> 為未減傷傷害、<code>D</code> 為套用減傷後但扣盾前的傷害：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>D = D0 × product(1 - r_i)</span></span>
<span class="line"><span>總減傷量 = D0 - D</span></span>
<span class="line"><span>各技能歸因量的合計必須等於總減傷量</span></span></code></pre></div><p>原建議將每項歸因設為 <code>D0 × r_i</code>，多減傷疊加時不守恆：原傷害 100、兩個 10% 減傷，承傷為 81，總減傷為 19，舊公式卻分配出 20。撤回該逐技能公式；分攤策略須另以來源與逐事件案例驗證。</p><p>HP loss 可能已扣盾、受 overkill、治療與同 frame 快照影響，不能直接代入 <code>D</code>。傷害類型、敵方 debuff、免疫、狀態覆蓋與盾的先後順序也須確認。證據不足時保留未知；完整模型驗收前不新增「含減傷 HPS」切換。</p><h2 id="rdps-後續工作" tabindex="-1">rDPS 後續工作 <a class="header-anchor" href="#rdps-後續工作" aria-label="Permalink to &quot;rDPS 後續工作&quot;">​</a></h2><p>倍率 buff 的 log-weight、target debuff matching、Crit／DH 條件模型與 direct／DoT event kind 仍待完成；詳見 <a href="./../../fflogs-rdps-validation-plan.html">rDPS 跟進計畫</a>。它們屬 Healing 主線穩定後的實作，不再另列為立即 P0。</p><p>技能 ID、數值與套用方向必須符合 <code>doc/buff-metadata-policy.md</code>，不能直接把舊建議中的技能清單當成已驗證 metadata。Crit／DH 模型須處理必爆必直、DoT 與資料不足，不能只憑本場觀測比例假裝已知角色屬性。</p>`,14)])])}const g=a(s,[["render",i]]);export{h as __pageData,g as default};
